            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "І возлюбили б душу чисту, і душу чорну, якби там в пеклі не стояли залізні пруття.", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Не вмерла Україна, і слава не поляже; поляже, як вода, по новой землі, як роса по чистім полю.", Author = "Тарас Шевченко" },
