            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Не так тії вороги люті, як добрії люди...", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Як умру, то поховайте мене на могилі, серед степу широкого, на Вкраїні милій.", Author = "Тарас Шевченко" },
