            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Чи знаєш ти, що ти дитина Божа?", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "І на цьому дивнім світі, не жалуючи сили, все ж іду за тим, що люблю, і вірю, що люблю.", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Учітеся, читайте, і чужому научайтесь, й свого не цурайтесь.", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Без господи, без землі, без хліба, без води, без науки, без мови — все пусте.", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Навкруги себе дивлюся, до людей придивляюся, і не бачу, чого ж боїться мужчина", Author = "Тарас Шевченко" },
