            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Подивись, як дніпро сивий, що той хлопець, розходився, розходився, що й не спинити.", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "І мертвим, і живим, і ненарожденним землякам моїм...", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Історія — найсправедливіший суддя.", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Хто слово своє сховав, той сам себе продавав.", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Життя — це путь, а не мета.", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Моя люба, моя рідна, моя Україна!", Author = "Тарас Шевченко" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Тарас_Шевченко", Text = "Україно, мати нащадків, будь здорова!", Author = "Тарас Шевченко" },
